import ajax from '@/utils/ajax';
import { action, observable } from 'mobx';
import { } from "@/components/custom"

type CodeType = "plugins" | "PluginProject"

class FeatchStore {

    items = {};

    getOptions = async (code: CodeType, params?: any) => {

        switch(code){
            case "plugins":
                return ajax.post('/apijson/get', {
                    "Plugins[]": {
                      "count": 0,
                      "Plugins": {
                        "@column": "id, name"
                      }
                    }
                }).then((res) => {
                    return res.Plugins.map((o) => ({ label: o.name, value: o.id }))
                });
            break;
        }
    }

    options = action((code: CodeType, params: any = {})=>{
        const key = `code=${code}&${JSON.stringify(params)}`;
        // console.log(key);
        if(!this.items[key]){
            this.items[key] = observable.array([]);
            this.getOptions(code, params).then(action((data) => {
                this.items[key].replace(data);
            }))
        }
        return this.items[key];
    })

}

export default FeatchStore;